import React, { useEffect, useState } from "react";
import { Modal, Button, Typography, Card, Divider, message, Skeleton, Space, Input } from "antd";
import { useSelector } from "react-redux";
import { fetchAllCouponList, validateCoupon } from "../../component/apiService/api";
import { useAuth } from "../../component/auth/context/authContext";
import { selectCartItems } from "../../redux/CartSlice";
import { Discount } from "../../config/common";
import { buildCouponProductInfo } from "../../utils/couponUtils";

const { Text } = Typography;

const CouponModal = ({ title, isOpen, onClose, onSelectCoupon, cartAmount = 0 }) => {
    const { token } = useAuth();
    const cartItems = useSelector(selectCartItems);
    const [isLoading, setIsLoading] = useState(false);
    const [isValidating, setIsValidating] = useState(false);
    const [couponData, setCouponData] = useState([]);
    const [enteredCode, setEnteredCode] = useState("");

    const getEligibleCartAmount = (coupon) => {
        const applicableBrands = coupon?.applicableBrands || [];
        const applicableProducts = coupon?.applicableProducts || [];
        const hasScopedApplicability = applicableBrands.length > 0 || applicableProducts.length > 0;

        if (!hasScopedApplicability) {
            return Number(cartAmount || 0);
        }

        const brandIds = new Set(applicableBrands.map((item) => String(item.brandId)));
        const productCodes = new Set(applicableProducts.map((item) => String(item.productCode || "").toUpperCase()));

        return (cartItems || []).reduce((total, item) => {
            const itemProductCode = String(item?.productCode || "").toUpperCase();
            const itemBrandId = item?.brandID;
            const isEligible =
                productCodes.has(itemProductCode) ||
                (itemBrandId !== undefined && itemBrandId !== null && brandIds.has(String(itemBrandId)));

            if (!isEligible) return total;

            return total + ((Number(item?.unit || 0)) * (Number(item?.bkdAmount || 0)));
        }, 0);
    };

    const getApplicabilityNote = (coupon) => {
        const brandCount = coupon?.applicableBrands?.length || 0;
        const productCount = coupon?.applicableProducts?.length || 0;

        if (!brandCount && !productCount) return null;
        if (brandCount && productCount) return `Applicable on ${brandCount} selected brands and ${productCount} selected products`;
        if (brandCount) return `Applicable on ${brandCount} selected brands`;
        return `Applicable on ${productCount} selected products`;
    };

    const visibleCoupons = (couponData || []).filter((coupon) => {
        const eligibleCartAmount = getEligibleCartAmount(coupon);
        return eligibleCartAmount > 0 && eligibleCartAmount >= Number(coupon?.minCartAmount || 0);
    });

    useEffect(() => {
        const showCouponsData = async () => {
            setIsLoading(true);
            try {
                await fetchAllCouponList(token)
                    .then((res) => {
                        if (res.status === 200) {
                            setCouponData(res.data.data || []);
                        }
                    })
                    .catch((err) => {
                        message.error(err.message);
                    });
            } catch (error) {
                message.error(error?.message || "Failed to fetch coupons");
            } finally {
                setIsLoading(false);
            }
        };

        if (isOpen) {
            showCouponsData();
            setEnteredCode("");
        }
    }, [isOpen, token]);

    const DeliveryBadge = () => (
        <div
            style={{
                position: "absolute",
                top: 10,
                right: -10,
                width: "80px",
                height: "15px",
                backgroundColor: "#4CAF50",
                color: "white",
                fontWeight: "bold",
                fontSize: 6,
                display: "flex",
                alignItems: "center",
                justifyContent: "center",
                transform: "rotate(-45deg)",
                boxShadow: "0 2px 5px rgba(0,0,0,0.2)",
                borderRadius: "0 0 4px 0",
                userSelect: "none",
            }}
        >
            DELIVERIES
        </div>
    );

    const getDiscountLabel = (coupon) => {
        if (coupon.discountType === Discount.DISCOUNT || coupon.discountType === "discount") {
            return coupon.discountValueType === "flat"
                ? `Rs.${coupon.discountValue} OFF`
                : `${coupon.discountValue}% OFF`;
        }
        if (coupon.discountType === Discount.CASHBACK || coupon.discountType === "cashback") {
            return `Rs.${coupon.discountValue} OFF`;
        }
        return `${coupon.discountValue} FREE`;
    };

    const getDiscountTitle = (coupon) => {
        if (coupon.discountType === Discount.DISCOUNT || coupon.discountType === "discount") {
            return coupon.discountValueType === "flat"
                ? `Save Rs.${coupon.discountValue} on this order!`
                : `Save ${coupon.discountValue}% on this order!`;
        }
        if (coupon.discountType === Discount.CASHBACK || coupon.discountType === "cashback") {
            return `Save Rs.${coupon.discountValue} on this order!`;
        }
        return `${coupon.discountValue} Free deliveries on this order!`;
    };

    const getDiscountDescription = (coupon) => {
        if (coupon?.description && String(coupon.description).trim()) {
            return coupon.description;
        }

        // if (coupon.discountType === Discount.DISCOUNT || coupon.discountType === "discount") {
        //     return coupon.discountValueType === "flat"
        //         ? `Use code ${coupon.couponCode} and get Rs.${coupon.discountValue} off on orders above Rs.${coupon.minCartAmount}. You can use this ${uses} more time${uses !== 1 ? "s" : ""}`
        //         : `Use code ${coupon.couponCode} and get ${coupon.discountValue}% off on orders above Rs.${coupon.minCartAmount}. You can use this ${uses} more time${uses !== 1 ? "s" : ""}`;
        // }
        // if (coupon.discountType === Discount.CASHBACK || coupon.discountType === "cashback") {
        //     return `Use code ${coupon.couponCode} and get Rs.${coupon.discountValue} off on orders above Rs.${coupon.minCartAmount}. You can use this ${uses} more time${uses !== 1 ? "s" : ""}`;
        // }
        // return `Use code ${coupon.couponCode} and get free delivery on orders above Rs.${coupon.minCartAmount}. You can use this ${uses} more time${uses !== 1 ? "s" : ""}`;

        return "";
    };

    const handleApplyCoupon = async () => {
        if (!enteredCode.trim()) {
            message.error("Please enter a coupon code");
            return;
        }
        setIsValidating(true);
        try {
            const res = await validateCoupon(token, {
                couponCode: enteredCode.trim(),
                cartAmount: cartAmount,
                productInfo: buildCouponProductInfo(cartItems)
            });
            if (res.status === 200) {
                onSelectCoupon(res.data.data);
                message.success("Coupon Applied Successfully!");
                onClose();
            }
        } catch (err) {
            message.error(err?.response?.data?.message || "Invalid coupon code");
        } finally {
            setIsValidating(false);
        }
    };

    const handleApplyFromCard = async (coupon) => {
        setIsValidating(true);
        try {
            const res = await validateCoupon(token, {
                couponCode: coupon.couponCode,
                cartAmount: cartAmount,
                productInfo: buildCouponProductInfo(cartItems)
            });
            if (res.status === 200) {
                onSelectCoupon(res.data.data);
                message.success("Coupon Applied Successfully!");
                onClose();
            }
        } catch (err) {
            message.error(err?.response?.data?.message || "Coupon is not applicable");
        } finally {
            setIsValidating(false);
        }
    };

    return (
        <Modal
            title={title}
            open={isOpen}
            onCancel={onClose}
            footer={null}
            centered
            bodyStyle={{ maxHeight: "60vh", overflowY: "auto" }}
        >
            {isLoading ? (
                <Skeleton active title={false} paragraph={{ rows: 6 }} />
            ) : (
                <>
                    <Divider style={{ margin: "15px 0" }} />

                    <Space.Compact style={{ width: "100%", marginBottom: "10px" }}>
                        <Input
                            placeholder="Enter Coupon Code"
                            value={enteredCode}
                            onChange={(e) => setEnteredCode(e.target.value)}
                            className="checkout-input"
                            onPressEnter={handleApplyCoupon}
                        />
                        <Button type="primary" onClick={handleApplyCoupon} loading={isValidating}>
                            Apply
                        </Button>
                    </Space.Compact>

                    {visibleCoupons?.map((coupon) => (
                        <Card
                            key={coupon._id || coupon.couponCode}
                            style={{
                                borderRadius: 16,
                                overflow: "hidden",
                                marginBottom: 18,
                                boxShadow: "0 2px 12px #eee",
                            }}
                            bodyStyle={{ padding: 0 }}
                            bordered={false}
                        >
                            <div style={{ display: "flex" }}>
                                <div
                                    style={{
                                        position: "relative",
                                        background: "#FF5722",
                                        color: "white",
                                        fontWeight: "bold",
                                        display: "flex",
                                        flexDirection: "column",
                                        justifyContent: "center",
                                        alignItems: "center",
                                        width: 48,
                                        minWidth: 48,
                                        borderRadius: "16px 0 0 16px",
                                        fontSize: 14,
                                        letterSpacing: 1,
                                    }}
                                >
                                    <div
                                        style={{
                                            writingMode: "vertical-rl",
                                            transform: "rotate(180deg)",
                                            textAlign: "center",
                                        }}
                                    >
                                        {getDiscountLabel(coupon)}
                                    </div>

                                    {(coupon.discountType === Discount.FREE_DELIVERY ||
                                        coupon.discountType === "freeDelivery") && <DeliveryBadge />}
                                </div>

                                <div
                                    style={{
                                        flex: 1,
                                        padding: "12px 16px 12px 16px",
                                        minHeight: 80,
                                        position: "relative",
                                    }}
                                >
                                    <div style={{ display: "flex", alignItems: "flex-start" }}>
                                        <Text strong style={{ fontSize: 16 }}>
                                            {coupon.couponCode}
                                        </Text>

                                        <Button
                                            type="default"
                                            size="small"
                                            style={{ marginLeft: "auto", fontWeight: "bold" }}
                                            onClick={() => handleApplyFromCard(coupon)}
                                            loading={isValidating}
                                        >
                                            APPLY
                                        </Button>
                                    </div>

                                    <Text type="success" style={{ fontWeight: "bold", fontSize: 14 }}>
                                        {getDiscountTitle(coupon)}
                                    </Text>

                                    <br />

                                    {getDiscountDescription(coupon) ? (
                                        <Text style={{ fontSize: 12, color: "#666" }}>
                                            {getDiscountDescription(coupon)}
                                        </Text>
                                    ) : null}

                                    {getApplicabilityNote(coupon) && (
                                        <>
                                            <br />
                                            <Text style={{ fontSize: 12, color: "#999" }}>
                                                {getApplicabilityNote(coupon)}
                                            </Text>
                                        </>
                                    )}
                                </div>
                            </div>
                        </Card>
                    ))}

                    {!visibleCoupons?.length && (
                        <Text type="secondary">No coupons are currently applicable to this cart.</Text>
                    )}
                </>
            )}
        </Modal>
    );
};

export default CouponModal;
